const server=await createServer({root,configFile:false,envFile:false,cacheDir:resolve(scratch,'vite-'+randomUUID()),plugins:[react(),tailwind(),{name:'dashboard-isolated-session',configureServer(s){s.middlewares.use('/__dashboard_session',async(req,res)=>{res.setHeader('Cache-Control','no-store');res.setHeader('Content-Type','application/json');res.end(await readFile(sessionPath,'utf8'));});}}],define:{'import.meta.env.VITE_BASE_URL':JSON.stringify('/api'),'import.meta.env.VITE_ASSET_BASE_URL':JSON.stringify(''),'import.meta.env.VITE_REFRESH_INTERVAL':JSON.stringify('300000')},server:{host:'127.0.0.1',port:5199,strictPort:true,proxy:{'/api':{target:session.origin,changeOrigin:true}}}});
